<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Kanban Board</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    min-height: 100vh;
    padding: 32px 24px;
    background: linear-gradient(135deg, #eef2f7 0%, #e4eaf3 100%);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    color: #1f2937;
  }

  .app { max-width: 1200px; margin: 0 auto; }

  /* ---------- Top bar ---------- */
  .app-header {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    margin-bottom: 26px;
  }

  .app-header h1 {
    font-size: 1.55rem;
    font-weight: 800;
    letter-spacing: -0.02em;
    color: #111827;
  }

  .app-header h1 span { color: #6366f1; }

  .add-form {
    display: flex;
    gap: 10px;
    flex: 1;
    min-width: 280px;
    max-width: 540px;
  }

  #new-card {
    flex: 1;
    padding: 11px 14px;
    font-size: 0.95rem;
    background: #fff;
    border: 1px solid #d7dce5;
    border-radius: 10px;
    outline: none;
    transition: border-color .15s, box-shadow .15s;
  }

  #new-card:focus {
    border-color: #6366f1;
    box-shadow: 0 0 0 3px rgba(99, 102, 241, .18);
  }

  #add-card {
    padding: 11px 18px;
    font-size: 0.95rem;
    font-weight: 600;
    color: #fff;
    background: #6366f1;
    border: none;
    border-radius: 10px;
    cursor: pointer;
    white-space: nowrap;
    transition: background .15s, transform .1s;
  }

  #add-card:hover { background: #4f46e5; }
  #add-card:active { transform: scale(.96); }

  /* ---------- Board & columns ---------- */
  .board {
    display: flex;
    gap: 20px;
    align-items: flex-start;
  }

  .column {
    flex: 1;
    min-width: 240px;
    min-height: 340px;
    display: flex;
    flex-direction: column;
    padding: 16px;
    background: #f5f7fb;
    border: 1px solid #e3e7ef;
    border-radius: 14px;
    transition: background .15s, box-shadow .15s;
  }

  .column.drag-over {
    background: #eef0ff;
    box-shadow: inset 0 0 0 2px #6366f1;
  }

  .col-header {
    display: flex;
    align-items: center;
    gap: 9px;
    margin-bottom: 14px;
    padding-bottom: 12px;
    border-bottom: 1px solid #e3e7ef;
  }

  .col-header h2 {
    font-size: 0.9rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .06em;
    color: #4b5563;
  }

  .dot { width: 9px; height: 9px; border-radius: 50%; flex-shrink: 0; }
  #col-todo  .dot { background: #6366f1; }
  #col-doing .dot { background: #f59e0b; }
  #col-done  .dot { background: #10b981; }

  .count {
    margin-left: auto;
    min-width: 26px;
    padding: 2px 9px;
    font-size: 0.8rem;
    font-weight: 700;
    text-align: center;
    border-radius: 999px;
  }

  #col-todo  .count { background: rgba(99,102,241,.13); color: #4f46e5; }
  #col-doing .count { background: rgba(245,158,11,.16); color: #b45309; }
  #col-done  .count { background: rgba(16,185,129,.15); color: #047857; }

  /* ---------- Cards ---------- */
  .cards {
    display: flex;
    flex-direction: column;
    gap: 10px;
    flex: 1;
    min-height: 60px;
  }

  .card {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    padding: 12px;
    background: #fff;
    border: 1px solid #e6e9f0;
    border-left: 3px solid #9ca3af;
    border-radius: 10px;
    box-shadow: 0 1px 2px rgba(16, 24, 40, .06);
    cursor: grab;
    user-select: none;
    transition: box-shadow .15s, transform .15s, opacity .15s;
  }

  #col-todo  .card { border-left-color: #6366f1; }
  #col-doing .card { border-left-color: #f59e0b; }
  #col-done  .card { border-left-color: #10b981; }

  .card:hover {
    box-shadow: 0 5px 14px rgba(16, 24, 40, .12);
    transform: translateY(-1px);
  }

  .card.dragging {
    opacity: .45;
    cursor: grabbing;
    transform: rotate(1.5deg);
  }

  .card-text {
    flex: 1;
    font-size: 0.92rem;
    line-height: 1.45;
    word-break: break-word;
  }

  .card-del {
    flex-shrink: 0;
    padding: 1px 7px;
    font-size: 1.15rem;
    line-height: 1.2;
    color: #9ca3af;
    background: transparent;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    transition: background .15s, color .15s;
  }

  .card-del:hover { background: #fee2e2; color: #dc2626; }

  @media (max-width: 820px) {
    .board { flex-direction: column; }
    .column { width: 100%; min-height: 0; }
  }
</style>
</head>
<body>
  <div class="app">
    <header class="app-header">
      <h1>Kanban<span>Board</span></h1>
      <form id="add-form" class="add-form" autocomplete="off">
        <input id="new-card" type="text" placeholder="What needs to be done?" maxlength="200">
        <button id="add-card" type="submit">+ Add Card</button>
      </form>
    </header>

    <main class="board">
      <section class="column" id="col-todo">
        <header class="col-header">
          <span class="dot"></span>
          <h2>To Do</h2>
          <span class="count">0</span>
        </header>
        <div class="cards"></div>
      </section>

      <section class="column" id="col-doing">
        <header class="col-header">
          <span class="dot"></span>
          <h2>In Progress</h2>
          <span class="count">0</span>
        </header>
        <div class="cards"></div>
      </section>

      <section class="column" id="col-done">
        <header class="col-header">
          <span class="dot"></span>
          <h2>Done</h2>
          <span class="count">0</span>
        </header>
        <div class="cards"></div>
      </section>
    </main>
  </div>

<script>
(function () {
  'use strict';

  var STORAGE_KEY = 'kanban-board-state-v1';
  var COLUMN_IDS = ['col-todo', 'col-doing', 'col-done'];

  var form = document.getElementById('add-form');
  var input = document.getElementById('new-card');
  var todoCards = document.querySelector('#col-todo .cards');
  var draggedCard = null;

  function uid() {
    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);
  }

  function createCard(id, text) {
    var card = document.createElement('div');
    card.className = 'card';
    card.setAttribute('draggable', 'true');
    card.dataset.id = id;

    var label = document.createElement('span');
    label.className = 'card-text';
    label.textContent = text;

    var del = document.createElement('button');
    del.type = 'button';
    del.className = 'card-del';
    del.title = 'Delete';
    del.setAttribute('aria-label', 'Delete card');
    del.textContent = '\u00D7';
    del.addEventListener('click', function () {
      card.remove();
      save();
      updateCounts();
    });

    card.appendChild(label);
    card.appendChild(del);

    card.addEventListener('dragstart', function (e) {
      draggedCard = card;
      card.classList.add('dragging');
      if (e.dataTransfer) {
        e.dataTransfer.effectAllowed = 'move';
        try { e.dataTransfer.setData('text/plain', id); } catch (err) {}
      }
    });

    card.addEventListener('dragend', function () {
      card.classList.remove('dragging');
      draggedCard = null;
      var over = document.querySelectorAll('.column.drag-over');
      for (var i = 0; i < over.length; i++) over[i].classList.remove('drag-over');
      save();
      updateCounts();
    });

    return card;
  }

  function getAfterElement(container, y) {
    var cards = container.querySelectorAll('.card:not(.dragging)');
    var closest = null;
    var closestOffset = -Infinity;
    for (var i = 0; i < cards.length; i++) {
      var box = cards[i].getBoundingClientRect();
      var offset = y - box.top - box.height / 2;
      if (offset < 0 && offset > closestOffset) {
        closestOffset = offset;
        closest = cards[i];
      }
    }
    return closest;
  }

  function updateCounts() {
    COLUMN_IDS.forEach(function (cid) {
      var col = document.getElementById(cid);
      col.querySelector('.count').textContent = col.querySelectorAll('.card').length;
    });
  }

  function save() {
    var state = [];
    COLUMN_IDS.forEach(function (cid) {
      var cards = document.getElementById(cid).querySelectorAll('.card');
      for (var i = 0; i < cards.length; i++) {
        state.push({
          id: cards[i].dataset.id,
          text: cards[i].querySelector('.card-text').textContent,
          col: cid
        });
      }
    });
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); } catch (e) {}
  }

  function load() {
    var state = [];
    try { state = JSON.parse(localStorage.getItem(STORAGE_KEY)) || []; } catch (e) {}
    if (!Array.isArray(state)) state = [];
    state.forEach(function (item) {
      if (!item || COLUMN_IDS.indexOf(item.col) === -1) return;
      var container = document.querySelector('#' + item.col + ' .cards');
      var text = item.text == null ? '' : String(item.text);
      container.appendChild(createCard(item.id || uid(), text));
    });
  }

  /* ----- Add new card (button click or Enter key) ----- */
  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var text = input.value.trim();
    if (!text) { input.value = ''; return; }
    todoCards.appendChild(createCard(uid(), text));
    input.value = '';
    input.focus();
    save();
    updateCounts();
  });

  /* ----- HTML5 drag-and-drop on columns ----- */
  COLUMN_IDS.forEach(function (cid) {
    var col = document.getElementById(cid);
    var container = col.querySelector('.cards');

    col.addEventListener('dragover', function (e) {
      e.preventDefault();
      if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
      col.classList.add('drag-over');
      if (draggedCard) {
        var after = typeof e.clientY === 'number' ? getAfterElement(container, e.clientY) : null;
        if (after) container.insertBefore(draggedCard, after);
        else container.appendChild(draggedCard);
      }
    });

    col.addEventListener('dragleave', function (e) {
      if (!col.contains(e.relatedTarget)) col.classList.remove('drag-over');
    });

    col.addEventListener('drop', function (e) {
      e.preventDefault();
      col.classList.remove('drag-over');

      var card = draggedCard;
      if (!card && e.dataTransfer) {
        var id = '';
        try { id = e.dataTransfer.getData('text/plain'); } catch (err) {}
        if (id) {
          var all = document.querySelectorAll('.card');
          for (var i = 0; i < all.length; i++) {
            if (all[i].dataset.id === id) { card = all[i]; break; }
          }
        }
      }
      if (!card) return;

      var after = e.clientY ? getAfterElement(container, e.clientY) : null;
      if (after) container.insertBefore(card, after);
      else container.appendChild(card);

      save();
      updateCounts();
    });
  });

  load();
  updateCounts();
})();
</script>
</body>
</html>
